import { requestToPromise, runTransaction } from "../db/database";
import { STORE_NAMES } from "../db/schema";
import type { SensitiveSettingsRecord } from "../db/types";
import type { AiSettings } from "./types";

const ID = "ai" as const;

/** Validate settings before they can reach IndexedDB or the network client. */
export function validateAiSettings(settings: AiSettings): void {
  if (
    typeof settings.apiUrl !== "string" ||
    typeof settings.model !== "string" ||
    typeof settings.apiKey !== "string" ||
    typeof settings.organizationId !== "string" ||
    typeof settings.customHeaders !== "object" ||
    settings.customHeaders === null
  ) {
    throw new Error("Invalid AI settings");
  }
  if (!settings.apiUrl.trim()) throw new Error("AI API URL is required");
  if (!settings.model.trim()) throw new Error("AI model is required");
  if (!settings.apiKey.trim()) throw new Error("AI API key is required");
  if (/[\r\n]/.test(settings.model) || /[\r\n]/.test(settings.apiKey) || /[\r\n]/.test(settings.organizationId)) {
    throw new Error("Invalid AI settings");
  }

  let parsed: URL;
  try {
    parsed = new URL(settings.apiUrl);
  } catch {
    throw new Error("Invalid AI API URL");
  }
  if (
    (parsed.protocol !== "https:" && parsed.protocol !== "http:") ||
    parsed.username ||
    parsed.password ||
    parsed.search ||
    parsed.hash ||
    !parsed.hostname
  ) {
    throw new Error("Invalid AI API URL");
  }

  if (Array.isArray(settings.customHeaders)) {
    throw new Error("Invalid AI custom headers");
  }
  for (const [name, value] of Object.entries(settings.customHeaders)) {
    if (!/^[!#$%&'*+.^_`|~0-9A-Za-z-]+$/.test(name) || /[\r\n]/.test(name)) {
      throw new Error("Invalid AI custom header name");
    }
    if (typeof value !== "string" || /[\r\n]/.test(value)) {
      throw new Error("Invalid AI custom header value");
    }
  }
}

function now(): string {
  return new Date().toISOString();
}

export async function getAiSettings(database: IDBDatabase): Promise<AiSettings | undefined> {
  const record = await runTransaction(database, STORE_NAMES.sensitiveSettings, "readonly", (tx) =>
    requestToPromise<SensitiveSettingsRecord | undefined>(tx.objectStore(STORE_NAMES.sensitiveSettings).get(ID)),
  );
  if (!record) return undefined;
  const { id: _id, createdAt: _createdAt, updatedAt: _updatedAt, ...settings } = record;
  return settings;
}

export async function saveAiSettings(database: IDBDatabase, settings: AiSettings): Promise<AiSettings> {
  validateAiSettings(settings);
  const existing = await runTransaction(database, STORE_NAMES.sensitiveSettings, "readonly", (tx) =>
    requestToPromise<SensitiveSettingsRecord | undefined>(tx.objectStore(STORE_NAMES.sensitiveSettings).get(ID)),
  );
  const timestamp = now();
  const record: SensitiveSettingsRecord = {
    ...settings,
    id: ID,
    createdAt: existing?.createdAt ?? timestamp,
    updatedAt: timestamp,
  };
  await runTransaction(database, STORE_NAMES.sensitiveSettings, "readwrite", (tx) =>
    requestToPromise(tx.objectStore(STORE_NAMES.sensitiveSettings).put(record)),
  );
  return settings;
}

export async function clearAiSettings(database: IDBDatabase): Promise<void> {
  await runTransaction(database, STORE_NAMES.sensitiveSettings, "readwrite", (tx) =>
    requestToPromise(tx.objectStore(STORE_NAMES.sensitiveSettings).delete(ID)),
  );
}

export const getSensitiveAiSettings = getAiSettings;
export const saveSensitiveAiSettings = saveAiSettings;
export const clearSensitiveSettings = clearAiSettings;
export const loadAiSettings = getAiSettings;
export const updateAiSettings = saveAiSettings;
import type { AiSettings } from "../settings/types";
import { validateAiSettings } from "../settings/secrets";

export interface AiChatMessage {
  role: "system" | "user" | "assistant";
  content: string;
}

export interface OpenAiClientOptions {
  fetch?: typeof fetch;
}

export interface AiCompletionRequest {
  messages: readonly AiChatMessage[];
}

function endpoint(baseUrl: string, path: string): string {
  return `${baseUrl.replace(/\/+$/, "")}/${path}`;
}

function requestHeaders(settings: AiSettings): Record<string, string> {
  const headers: Record<string, string> = { ...settings.customHeaders };
  for (const name of Object.keys(headers)) {
    if (["authorization", "openai-organization", "content-type"].includes(name.toLowerCase())) {
      delete headers[name];
    }
  }
  headers.Authorization = `Bearer ${settings.apiKey}`;
  if (settings.organizationId.trim()) {
    headers["OpenAI-Organization"] = settings.organizationId;
  } else {
    delete headers["OpenAI-Organization"];
  }
  return headers;
}

function validateMessages(messages: readonly AiChatMessage[]): void {
  if (!Array.isArray(messages) || messages.length === 0) throw new Error("AI messages are required");
  for (const message of messages) {
    if (!["system", "user", "assistant"].includes(message.role) || typeof message.content !== "string" || !message.content.trim()) {
      throw new Error("Invalid AI message");
    }
  }
}

/** Small OpenAI-compatible transport. It deliberately has no logging side effects. */
export class OpenAiClient {
  readonly #settings: AiSettings;
  readonly #fetch: typeof fetch;

  constructor(settings: AiSettings, fetchImpl?: typeof fetch | OpenAiClientOptions, options: OpenAiClientOptions = {}) {
    this.#settings = { ...settings, customHeaders: { ...settings.customHeaders } };
    const suppliedFetch = typeof fetchImpl === "function" ? fetchImpl : fetchImpl?.fetch;
    this.#fetch = suppliedFetch ?? options.fetch ?? globalThis.fetch.bind(globalThis);
  }

  async testConnection(): Promise<void> {
    validateAiSettings(this.#settings);
    const response = await this.#fetch(endpoint(this.#settings.apiUrl, "models"), {
      method: "GET",
      headers: requestHeaders(this.#settings),
      body: undefined,
    });
    if (!response.ok) throw new Error(`AI connection failed (${response.status})`);
  }

  async complete(messagesOrRequest: readonly AiChatMessage[] | AiCompletionRequest): Promise<string> {
    validateAiSettings(this.#settings);
    const messages = "messages" in messagesOrRequest ? messagesOrRequest.messages : messagesOrRequest;
    validateMessages(messages);
    const response = await this.#fetch(endpoint(this.#settings.apiUrl, "chat/completions"), {
      method: "POST",
      headers: (() => {
        const headers = requestHeaders(this.#settings);
        headers["Content-Type"] = "application/json";
        return headers;
      })(),
      body: JSON.stringify({ model: this.#settings.model, messages }),
    });
    if (!response.ok) throw new Error(`AI request failed (${response.status})`);
    let payload: unknown;
    try {
      payload = await response.json();
    } catch {
      throw new Error("AI response was not valid JSON");
    }
    const content = (payload as { choices?: Array<{ message?: { content?: unknown } }> })
      .choices?.[0]?.message?.content;
    if (typeof content !== "string") throw new Error("AI response did not contain message content");
    return content;
  }
}

export function createOpenAiClient(settings: AiSettings, fetchImpl?: typeof fetch): OpenAiClient {
  return new OpenAiClient(settings, fetchImpl);
}
